/** Illustration de secours quand un produit n'a pas de photo. */
export function fallbackArt(type: string, name = ""): string {
  const n = name.toLowerCase();
  if (type === "gaz") {
    if (n.includes("détendeur") || n.includes("detendeur") || n.includes("tuyau")) return img_gaz_detendeur;
    if (n.includes("neuve") || n.includes("neuf")) return img_gaz_neuve;
    if (n.includes("6")) return img_gaz_6kg;
    return img_gaz_12kg;
  }
  if (type === "carburant") {
    const gasoil = n.includes("gasoil") || n.includes("diesel");
    if (n.includes("bidon")) return gasoil ? img_carb_bidon_gasoil : img_carb_bidon_essence;
    return gasoil ? img_carb_gasoil : img_carb_essence;
  }
  if (n.includes("consigne")) return img_eau_bonbonne_consigne;
  if (n.includes("sachet")) return img_eau_sachets;
  if (n.includes("12")) return img_eau_pack12;
  if (n.includes("pack") || n.includes("6")) return img_eau_pack6;
  return img_eau_bonbonne;
}

